TP.register({id:"lp2-g3",lp:2,grade:"3",mode:"curriculum",checks:1,nextGrade:"4th grade",build(E){const F=E.F;const STORY_TITLE="The Last Apple";const STORY=["Tess and her neighbor, Mr. Park, picked apples all morning. By noon, six baskets were full. Only one apple was left on the old tree. It hung from the very top branch, round and red.","“I want that one,” said Tess. She stood on her toes, but the apple was too high. She jumped, but it was still too high. She shook the trunk, and the apple did not move.","Mr. Park pointed to the tall ladder by the shed. “Go slowly,” he said. “I will hold it steady.”","Tess looked up. Her hands felt cold. She climbed one step and stopped. The ground looked far away. “You can come down if you want,” said Mr. Park. Tess took a deep breath and kept going.","The ladder was taller than it looked from the ground. Each step felt narrower than the one below it, and the whole tree seemed to lean whenever the wind moved through the branches. Tess kept her eyes on the rung in front of her face instead of on the grass below. Behind her, Mr. Park talked the whole time about nothing important, about the weather and about the trees he had planted when he was young, and his steady voice made the climb feel shorter.","At the top, she reached out and twisted the apple. It popped off into her hand. Back on the ground, Tess did not eat the apple. She cut it in half and gave one piece to Mr. Park. “You held the ladder,” she said. “So half is yours.”"].join("\n\n");const CIDER_TITLE="Cider Day";const CIDER="It was cider day at the orchard. “Can you lend me a hand?” called Aunt Jo. Mateo ran over. “I am all ears,” he said. “What do I do?” Aunt Jo showed him the cider press. “Turn this crank,” she said. The crank was heavy. Mateo pushed and pushed until his arms felt like noodles. Sweet juice dripped into the bucket. “Hold your horses!” said Aunt Jo. “The bucket is full.” Mateo let go of the crank and smiled.";const BEES_TITLE="Bees at Work";const BEES=["An apple tree cannot make apples all by itself. It needs help from bees.","In spring, apple trees are covered with blossoms. Each blossom holds a yellow dust called pollen. A bee lands on a blossom to drink sweet nectar. While the bee drinks, pollen sticks to its fuzzy body. Then the bee flies to a blossom on another tree, and some of the pollen rubs off. Now that blossom can start to grow into an apple.","The bees are not trying to help the tree. They are just looking for food. Still, one bee can visit hundreds of blossoms in a single day. That is why many farmers bring beehives into the orchard each spring. The hives stay until the blossoms are gone. Without bees, an orchard would grow very few apples."].join("\n\n");const YEAR_TITLE="An Apple Tree’s Year";const YEAR="In spring, an apple tree grows pink and white blossoms. In summer, small green apples grow where the blossoms were. Farmers water the trees when the weather is dry. By fall, the apples are ripe. Workers climb ladders and fill baskets with fruit. Then the tree drops its leaves. In winter, the tree rests. Farmers cut off old branches so that new ones have room to grow.";const WORDS=["basket","blossom","orchard","unpack","refill","seedless","helpful","slowly","crunchy","unbroken","replanted","wonderful"];function appleAt(x,y,r){return`<line x1="${x}" y1="${y-r}" x2="${x+2}" y2="${y-r-6}" stroke="var(--ink)" stroke-width="2.5" stroke-linecap="round"/><ellipse cx="${x+7}" cy="${y-r-3}" rx="5" ry="2.6" fill="var(--sea)"/><circle cx="${x}" cy="${y}" r="${r}" fill="var(--coral)" stroke="var(--ink)" stroke-width="2"/>`}function box(n,perRow,rows,cell){cell=cell||42;rows=rows||Math.max(1,Math.ceil(n/perRow));const W=perRow*cell+20,H=rows*cell+24;let s=`<svg viewBox="0 0 ${W} ${H}" width="${W}" role="img" aria-label="A box with ${n} apples"><rect x="4" y="4" width="${W-8}" height="${H-8}" rx="12" fill="var(--surface)" stroke="var(--gold-ink)" stroke-width="4"/>`;for(let k=0;k<n;k++){const c=k%perRow,r=Math.floor(k/perRow);s+=appleAt(10+c*cell+cell/2,16+r*cell+cell/2,cell*.33)}return s+"</svg>"}function looseApples(n,perRow){const cell=42,rows=Math.ceil(n/perRow),W=perRow*cell+8,H=rows*cell+12;let s=`<svg viewBox="0 0 ${W} ${H}" width="${W}" role="img" aria-label="${n} apples">`;for(let k=0;k<n;k++){const c=k%perRow,r=Math.floor(k/perRow);s+=appleAt(4+c*cell+cell/2,10+r*cell+cell/2,cell*.33)}return s+"</svg>"}function treeRows(rows,cols){const c=56,W=cols*c+12,H=rows*c+12;let s=`<svg viewBox="0 0 ${W} ${H}" width="${W}" role="img" aria-label="${rows} rows of ${cols} trees">`;for(let r=0;r<rows;r++)for(let k=0;k<cols;k++){const x=6+k*c+c/2,y=6+r*c;s+=`<rect x="${x-4}" y="${y+30}" width="8" height="18" fill="var(--gold-ink)"/><circle cx="${x}" cy="${y+22}" r="17" fill="var(--sea)" stroke="var(--ink)" stroke-width="2"/><circle cx="${x-6}" cy="${y+18}" r="3" fill="var(--coral)"/><circle cx="${x+6}" cy="${y+26}" r="3" fill="var(--coral)"/>`}return s+"</svg>"}function group(inner,label){return`<div style="text-align:center"><div style="display:flex;gap:10px;flex-wrap:wrap;justify-content:center;align-items:center">${inner}</div><p class="fig-label" style="margin:4px 0 0">${label}</p></div>`}function noteBoxes(a,b){const bx=t=>`<div style="border:3px dashed var(--line);border-radius:16px;min-width:250px;min-height:100px;padding:8px 16px;background:var(--surface)"><p class="fig-label" style="margin:0;font-size:1.4rem">${t}</p></div>`;return`<div class="figure">${bx(a)}${bx(b)}</div>`}function steps(list){return`<div class="row center" style="gap:8px;flex-wrap:wrap;margin:14px 0">${list.map((t,i)=>`<span class="pill" style="font-size:1.2rem">${i+1}. ${t}</span>`).join("")}</div>`}const checklist=items=>`<ul class="qlist" style="margin-top:14px">${items.map(x=>`<li>${x}</li>`).join("")}</ul>`;const pills=items=>`<div class="row center" style="margin-top:20px;gap:18px;flex-wrap:wrap">${items.map(x=>`<span class="pill" style="font-size:1.4rem">${x}</span>`).join("")}</div>`;function dotPlot(o){const W=o.width||560,x0=50,x1=W-50,n=Math.round((o.max-o.min)/o.step);const val=i=>+(o.min+i*o.step).toFixed(4),X=i=>x0+i*(x1-x0)/n;const maxc=Math.max(1,...Object.values(o.counts||{})),H=76+maxc*24;let s=`<svg viewBox="0 0 ${W} ${H+28}" width="${W}" role="img" aria-label="${o.alt||"Dot plot"}">`;s+=`<line x1="${x0-18}" y1="${H-42}" x2="${x1+18}" y2="${H-42}" stroke="var(--fig-ink)" stroke-width="3" stroke-linecap="round"/>`;for(let i=0;i<=n;i++){const v=val(i),x=X(i),c=(o.counts||{})[v]||0;s+=`<line x1="${x}" y1="${H-50}" x2="${x}" y2="${H-34}" stroke="var(--fig-ink)" stroke-width="2.4"/>`;s+=`<text x="${x}" y="${H-10}" font-size="17" text-anchor="middle" fill="var(--ink)">${o.labels&&o.labels[v]||v}</text>`;for(let k=0;k<c;k++)s+=`<circle cx="${x}" cy="${H-60-k*24}" r="8.5" fill="var(--coral)" stroke="var(--fig-ink)" stroke-width="2"/>`}if(o.title)s+=`<text x="${W/2}" y="${H+20}" font-size="17" font-weight="700" text-anchor="middle" fill="var(--ink)">${o.title}</text>`;return s+"</svg>"}const TOUR="Welcome to the orchard. Here is how the picking tour works. First, a wagon takes your group out to the rows of trees. A guide shows you how to twist an apple off the branch so the stem stays on, because an apple with no stem does not keep as long. Then you fill one bag on your own. Last, you carry the bag back to the barn, where it is weighed. Everything in your bag is yours to take home.";const HAND_TITLE="Picking by Hand";const HAND="At a small orchard, every apple is picked by hand. Workers carry canvas bags and climb ladders to reach the high branches. They twist each apple off so the stem stays on the fruit. Hand picking takes a long time, but the apples are not bruised, so they can be sold whole at a farm stand.";const MACH_TITLE="Picking by Machine";const MACH="At a very large orchard, a machine does part of the work. A shaker grips the trunk and shakes the whole tree at once. The apples drop onto a wide catching frame and roll into a bin. One tree is emptied in about a minute. Shaking bruises some of the fruit. So apples picked this way are usually pressed into juice.";const STOPS=[{id:1,title:"Apple Word Pick",short:"Word Pick",parts:[{std:["RF.3.3"],kind:"words",words:WORDS,n:12,dur:90,dir:"Read each word out loud. If a word is long, break it into parts first.",desc:"reading words with prefixes, suffixes, and more than one syllable",key:["Read each word: basket, blossom, orchard, unpack, refill, seedless, helpful, slowly, crunchy, unbroken, replanted, wonderful.","Watch for: two-syllable words (basket, blossom, orchard), prefixes un- and re- (unpack, refill, unbroken, replanted), suffixes -less, -ful, -ly, -y (seedless, helpful, slowly, crunchy), and three-syllable words (unbroken, replanted, wonderful).","Optional check of word parts: ask what un- means in unpack (not, or the opposite of) and what -less means in seedless (without)."]}]},{id:2,title:"Crates and Rows",short:"Crates",parts:[{std:["3.OA.A.1"],dur:135,dir:"Look at the pictures. Answer out loud. Write your equations on your paper and hold them up.",desc:"telling what the numbers in a multiplication equation mean with equal groups and rows",fig:()=>`<div class="figure" style="gap:40px;align-items:flex-start">${group(box(6,3)+box(6,3)+box(6,3),"Picture A: crates of apples")}${group(treeRows(4,7),"Picture B: rows of apple trees")}</div>`,qs:["Picture A: How many crates are there? How many apples are in each crate?","Write a multiplication equation for Picture A. Tell what each number means.","Write a multiplication equation for Picture B. Tell what each number means.","True or false: 2 × 9 means the same thing as 2 + 9. Tell why."],key:["3 crates with 6 apples in each crate. Partial: one of the two counts given is approaching. (3.OA.A.1)","3 × 6 = 18. The 3 is the number of crates (groups), the 6 is the number of apples in each crate, and 18 is the total. Accept 6 × 3 = 18 when the student explains it. Partial: the equation right with no meaning for each number is approaching. (3.OA.A.1)","4 × 7 = 28. 4 rows with 7 trees in each row, 28 trees in all. 7 × 4 = 28 read as 7 columns of 4 is also correct. Partial: the equation right with no meaning for each number is approaching. (3.OA.A.1)","False. 2 × 9 means 2 groups of 9, which is 9 + 9 = 18. 2 + 9 is only 11. Partial: saying false with no totals worked out is approaching. (3.OA.A.1)"]}]},{id:3,title:"Up the Ladder",short:"Ladder Read",parts:[{std:["RF.3.4"],kind:"read",n:0,label:"words read correctly",dur:175,dir:"Read the story out loud. Use your best reading voice.",desc:"a grade-level story read aloud",html:()=>F.passage(STORY,STORY_TITLE),key:["__WC__ words, not counting the title. Time 1 minute and mark errors and self-corrections on your own copy. Let the student finish the passage.","Fall grade 3 benchmark: about 83 words correct per minute (Hasbrouck and Tindal 2017, fall 50th percentile). The passage length is set from the highest grade 3 figure on that same table, the spring 90th percentile of about 166 words correct per minute, so the minute ends before the text does even for the fastest reader and the score measures the reading rather than the length of the page.","Note pace, phrasing, and expression. Listen for a change in voice when Tess and Mr. Park talk."]}]},{id:4,title:"The Last Apple",short:"Last Apple",parts:[{std:["RL.3.1"],dur:150,dir:"Read the story. Then answer out loud. Look back at the story to prove each answer.",desc:"story questions answered by pointing to the exact words in the text",html:()=>F.passage(STORY,STORY_TITLE,true),qs:["How many baskets were full by noon? Read the sentence that tells you.","What three things did Tess try before she used the ladder? Look back at the story.","Which sentence tells you Tess was not sure about climbing?","Why did Tess give half of the apple to Mr. Park? Which sentence tells you?"],key:["Six. Reads “By noon, six baskets were full.” (RL.3.1)","She stood on her toes, she jumped, and she shook the trunk. All three come from the second paragraph. (RL.3.1)","Reads “She climbed one step and stopped.” Also accept “Her hands felt cold.” or “The ground looked far away.” (RL.3.1)","He helped her by holding the ladder. Points to “You held the ladder,” she said. “So half is yours.” (RL.3.1)"]}]},{id:5,title:"Share the Harvest",short:"Share It",parts:[{std:["3.OA.A.2"],dur:135,dir:"Look at the pictures. Answer out loud. Write your equations on your paper and hold them up.",desc:"telling what the numbers in a division equation mean with equal shares and equal groups",fig:()=>`<div class="figure" style="gap:40px;align-items:flex-start">${group(looseApples(12,6)+`<div style="display:flex;gap:8px">${box(0,2,2)}${box(0,2,2)}${box(0,2,2)}</div>`,"Picture A: 12 apples and 3 empty crates")}${group(box(5,5)+box(5,5)+box(5,5),"Picture B: 15 apples packed in bags of 5")}</div>`,qs:["Picture A: Share the 12 apples equally among the 3 crates. How many apples go in each crate?","Write a division equation for Picture A. Tell what each number means.","Write a division equation for Picture B. What does the answer tell you?","21 ÷ 3 = 7. Story 1: 21 apples are shared equally among 3 crates. Story 2: 21 apples are put into bags of 3. What does the 7 mean in each story?"],key:["4 apples in each crate. Partial: 4 with no account of what it counts is approaching. (3.OA.A.2)","12 ÷ 3 = 4. 12 is the total number of apples, 3 is the number of crates (equal shares), and 4 is the number of apples in each crate. Partial: the equation right with no meaning for each number is approaching. (3.OA.A.2)","15 ÷ 5 = 3. The 3 is the number of bags (the number of groups of 5). 15 ÷ 3 = 5 is also correct when the student says the 5 is the number of apples in each bag. Partial: the equation right with no account of what the answer tells you is approaching. (3.OA.A.2)","Story 1: 7 apples in each crate. Story 2: 7 bags. Both parts are needed. Partial: one of the two stories answered is approaching. (3.OA.A.2)"]}]},{id:6,title:"Cider Press Sayings",short:"Cider Sayings",parts:[{std:["RL.3.4"],dur:80,dir:"Read the story. Then answer out loud.",desc:"literal and nonliteral meanings of phrases in a story",html:()=>F.passage(CIDER,CIDER_TITLE,true),qs:["Aunt Jo asks, “Can you lend me a hand?” Does she want Mateo’s real hand? What does she mean?","Mateo says, “I am all ears.” What does he mean?","Aunt Jo says, “Hold your horses!” Are there horses in the story? What does she mean?","Which sentence means exactly what it says? A: “The crank was heavy.” B: “His arms felt like noodles.”"],key:["No. She wants him to help her. It is not literal. (RL.3.4)","He is listening closely and is ready to hear what to do. (RL.3.4)","No horses. She means stop or wait, because the bucket is full. (RL.3.4)","A is literal. B is nonliteral: his arms felt tired and floppy, not like real noodles. (RL.3.4)"]}]},{id:7,title:"Farm Stand Signs",short:"Farm Signs",parts:[{title:"Sign Fixer",std:["L.3.1"],dur:80,dir:"Each sign has one mistake. Say the whole sentence the right way.",desc:"fixing spoken grammar mistakes (plurals, verb tense, agreement, comparing words)",qs:["Two mouses ran under the apple cart.","The bees is busy today.","Yesterday we pick ten baskets of apples.","She eated the biggest apple.","This apple is more sweeter than that one."],key:["Two mice ran under the apple cart. (L.3.1, irregular plural noun)","The bees are busy today. (L.3.1, subject-verb agreement)","Yesterday we picked ten baskets of apples. (L.3.1, simple past tense)","She ate the biggest apple. (L.3.1, irregular past tense verb)","This apple is sweeter than that one. (L.3.1, comparative adjective)"]},{title:"Word Jobs",std:["L.3.1"],dur:75,dir:"Answer out loud.",desc:"spoken grammar items (plural nouns, future tense, agreement, verbs and adjectives)",qs:["Say the word for more than one: one leaf, two ____.","Say the sentence with the right verb: Tomorrow we ____ the apples. (wash)","Say the sentence with the right word: The farmer and her dog ____ to the barn every morning. (walk or walks)","Read this sentence: The children carry heavy baskets. Which word tells what the children do? Which word describes the baskets?"],key:["leaves (L.3.1, irregular plural noun)","Tomorrow we will wash the apples. (L.3.1, simple future tense)","walk. Two are walking, so the verb is walk. (L.3.1, subject-verb agreement)","carry is the verb. heavy is the adjective. Both are needed. (L.3.1, what verbs and adjectives do in a sentence)"]}]},{id:8,title:"Farm Stand Math",short:"Stand Math",parts:[{std:["3.OA.A.1"],dur:120,dir:"Answer out loud. For number 3, draw on your paper and hold it up.",desc:"matching multiplication to equal-group stories and drawings",qs:["A farm stand has 6 bags. Each bag holds 5 apples. Which one tells how many apples in all: 6 + 5 or 6 × 5? Tell why.","Tell an orchard story problem for 3 × 9.","Draw a picture that shows 2 × 8.","Would you rather have 4 bags with 5 apples in each? Or 3 bags with 7 apples in each? Tell how many apples each choice gives you."],key:["6 × 5. There are 6 equal groups with 5 in each group, so 30 apples in all. Partial: choosing 6 × 5 with no reason is approaching. (3.OA.A.1)","A story with 3 equal groups of 9, or 9 groups of 3, and 27 in all. Example: 3 trees with 9 apples on each tree. Partial: a story with the right numbers but no equal groups is approaching. (3.OA.A.1)","2 groups of 8, 8 groups of 2, or an array with 2 rows of 8. 16 in all. Partial: a picture with 16 things not in equal groups is approaching. (3.OA.A.1)","4 bags of 5 is 20 apples. 3 bags of 7 is 21 apples. Either pick is fine when both totals are right. Partial: one of the two totals right is approaching. (3.OA.A.1)"]}]},{id:9,title:"Busy Bees",parts:[{std:["RI.3.1"],dur:150,dir:"Read the text. Then answer out loud. Look back at the text to prove each answer.",desc:"asking and answering questions about an informational text using the exact words in the text",html:()=>F.passage(BEES,BEES_TITLE,true),qs:["Why does a bee land on an apple blossom? Which sentence tells you?","How does pollen get from one tree to another tree? Use the text.","Why do many farmers bring beehives into the orchard each spring? Which sentence proves it?","Your turn to be the teacher. Ask one question that this text answers. Start with What, How, or Why."],key:["To drink sweet nectar. Points to “A bee lands on a blossom to drink sweet nectar.” (RI.3.1)","Pollen sticks to the bee’s fuzzy body. When the bee flies to a blossom on another tree, some pollen rubs off. (RI.3.1)","Apple trees need bees to make apples. Points to “Without bees, an orchard would grow very few apples,” “It needs help from bees,” or “Still, one bee can visit hundreds of blossoms in a single day.” (RI.3.1)","Asks a question the text can answer, such as: What is pollen? How many blossoms can one bee visit in a day? How long do the hives stay? (RI.3.1, asks questions)"]}]},{id:10,title:"Farm Stand Writer",short:"Write",parts:[{alt:{group:"write",key:"opinion",label:"Opinion",icon:"💬",hint:"Pick the better apple treat"},std:["W.3.1"],n:4,label:"checks met",dur:270,dir:"Write on your paper. When you finish, hold it up or read it to your teacher.",desc:"an opinion writing piece",html:()=>`<p class="big">Which is the better apple treat: fresh apple slices or warm apple pie? Write your opinion. Give two reasons. Write 4 to 6 sentences.</p>${checklist(["Say your opinion","Give two reasons","Use a linking word: because, also, for example","End with a closing sentence"])}`,key:["Introduces the topic and states an opinion (W.3.1)","Gives reasons that support the opinion (W.3.1)","Uses linking words such as because, also, therefore, since, for example (W.3.1)","Ends with a concluding sentence (W.3.1)"]},{alt:{group:"write",key:"facts",label:"Explain",icon:"📘",hint:"Teach how apples become cider"},std:["W.3.2"],n:4,label:"checks met",dur:270,dir:"Write on your paper. When you finish, hold it up or read it to your teacher.",desc:"an informative writing piece",html:()=>`<p class="big">Write to teach someone how apples become cider. Use the steps in the fact box. Write 4 to 6 sentences.</p><p class="fig-label" style="text-align:center;margin:14px 0 0">Fact box: from apples to cider</p>${steps(["Wash the apples","Grind them into mush","Press the mush to squeeze out the juice","Pour the juice into jugs and keep it cold"])}${checklist(["Name your topic","Give the facts in your own sentences","Use a linking word: first, next, also, then","End with a closing sentence"])}`,key:["Introduces the topic: how apples become cider (W.3.2)","Develops the topic with facts and details from the fact box: wash, grind into mush, press out the juice, pour into jugs and keep cold (W.3.2)","Uses linking words such as first, next, also, another, then (W.3.2)","Ends with a concluding sentence (W.3.2)"]},{alt:{group:"write",key:"story",label:"Story",icon:"✨",hint:"A bee follows you through the orchard"},std:["W.3.3"],n:4,label:"checks met",dur:270,dir:"Write on your paper. When you finish, hold it up or read it to your teacher.",desc:"a narrative writing piece",html:()=>`<p class="big">One morning, a friendly bee follows you all the way through the orchard. Write the story of what happens. Write 4 to 6 sentences.</p>${pills(["First","Next","Then","Last"])}${checklist(["Tell who is in the story and where it happens","Tell what happens in order","Tell what someone says, thinks, or feels","Give your story an ending"])}`,key:["Sets up the situation and who is in the story (W.3.3)","Events happen in a clear order, with time words such as first, next, then, after that (W.3.3)","Tells actions, thoughts, or feelings, or uses dialogue (W.3.3)","Has an ending that wraps up the story (W.3.3)"]}]},{id:11,title:"Cider Jug Shares",short:"Jug Shares",parts:[{std:["3.OA.A.2"],dur:120,dir:"Answer out loud. For number 4, draw on your paper and hold it up.",desc:"matching division to sharing and grouping stories and drawings",qs:["Which story matches 30 ÷ 5? Story A: A shelf has 30 jugs of cider. Then 5 jugs are sold. Story B: 30 jugs of cider are put on 5 shelves, with the same number on each shelf.","Spot the mistake. Kai says, “10 ÷ 2 means 10 groups of 2.” Is Kai right? Tell why.","Tell a cider story problem for 18 ÷ 2. What does the answer mean in your story?","Draw a picture that shows 14 ÷ 2."],key:["Story B. 30 jugs shared equally among 5 shelves is 6 jugs on each shelf. Story A is subtraction. Partial: choosing Story B with no reason is approaching. (3.OA.A.2)","No. 10 ÷ 2 means 10 things split into 2 equal groups (5 in each group) or into groups of 2 (5 groups). 10 groups of 2 is 10 × 2. Partial: saying no with no correct meaning given is approaching. (3.OA.A.2)","A story where 18 things are shared into 2 equal groups, or put into groups of 2. The student says the 9 is the number in each group, or the number of groups, to match the story. Partial: a story with the right numbers but no equal groups is approaching. (3.OA.A.2)","14 things in 2 equal groups of 7, or 14 things in groups of 2 that make 7 groups. Partial: a picture with 14 things not in equal groups is approaching. (3.OA.A.2)"]}]},{id:12,title:"Note Baskets",parts:[{std:["W.3.8"],n:3,label:"checks met",dur:120,dir:"Read the text. Write your notes on your paper and hold it up.",desc:"taking brief notes from a text and sorting them into given categories",html:()=>`${F.passage(YEAR,YEAR_TITLE,true)}<p class="big">Make two boxes on your paper. Label them like the boxes below. Write one short note from the text in each box.</p>${noteBoxes("What the tree does","What people do")}<p class="small" style="text-align:center;font-size:1.2rem">A note is just a few words. You do not need a whole sentence.</p>`,key:["Tree box: a fact about the tree, such as grows blossoms in spring, grows small green apples in summer, apples are ripe by fall, drops its leaves, rests in winter. (W.3.8, sorts evidence into the given category)","People box: a fact about people, such as farmers water the trees, workers climb ladders, workers fill baskets, farmers cut off old branches. (W.3.8, sorts evidence into the given category)","Notes are brief: a few words or a short phrase, not a whole sentence copied from the text. (W.3.8, brief notes)"]}]},{id:13,title:"Tour Talk",short:"Tour Talk",parts:[{title:"Listen for the Main Idea",std:["SL.3.2"],n:3,dur:45,read:TOUR,dir:"Listen while your teacher reads the guide's welcome. It is not on your screen. Then answer out loud.",desc:"finding the main idea and supporting details of information read aloud",html:()=>`<p class="big" style="text-align:center">Listen only. Your teacher will read the orchard guide's welcome once.</p>`,qs:["What is the main idea of what you just heard?","Give two details that support that main idea.","Why does the guide say to twist the apple off so the stem stays on?"],key:["How the apple picking tour works, from start to finish. Any wording that names the whole process counts. A single detail, such as a wagon, is not the main idea (SL.3.2)","Two of these: a wagon takes the group to the trees, a guide shows how to twist an apple off, you fill one bag yourself, the bag is weighed at the barn, what you pick is yours to keep (SL.3.2)","An apple with no stem does not keep as long (SL.3.2)","Read it once. If you read it a second time, write that down."]},{title:"Tell Me About the Tools",std:["SL.3.4"],n:3,label:"checks met",dur:45,dir:"Talk for about a minute. Speak clearly and look up while you talk.",desc:"reporting on a topic with facts and descriptive details, in clear speech",html:()=>`<p class="big">A worker picks apples at an orchard. Tell me what they need. What is each thing for?</p>${pills(["a ladder","a bag or basket","a crate"])}`,key:["Names facts that fit the topic: a ladder to reach high branches, a bag or basket to carry what is picked, a crate to hold the apples, gloves, a wagon (SL.3.4)","Adds descriptive detail to at least one of them, such as how big it is, what it is made of, or how it is used (SL.3.4)","Speaks at a pace you can follow, loud enough to hear, in sentences (SL.3.4)"]}]},{id:14,title:"Two Ways to Pick",short:"Two Ways",parts:[{std:["RI.3.9"],n:3,dur:60,dir:"Read both short texts. Then answer out loud. Look back at either text to prove your answer.",desc:"comparing and contrasting the key points of two texts on the same topic",html:()=>`${F.passage(HAND,HAND_TITLE,true)}${F.passage(MACH,MACH_TITLE,true)}`,qs:["What is the same about the two ways of picking?","What is different about how long each way takes? Use a detail from each text.","A farmer wants to sell whole apples at a farm stand. Which way should she use, and why? Use a detail from each text."],key:["Both are ways of getting the apples off the tree and into a bag or bin at harvest time. Any true point both texts share counts (RI.3.9)","Hand picking takes a long time. The machine empties one tree in about a minute. Both details are needed (RI.3.9)","Hand picking, because hand picked apples are not bruised and can be sold whole, while shaking bruises some fruit so those apples go to juice (RI.3.9)"]}]},{id:15,title:"Orchard Numbers",short:"Numbers",parts:[{title:"Two Steps",std:["3.OA.D.8"],n:4,dur:150,dir:"Solve on your paper. Write an equation with a letter for the unknown. Show your work and hold it up.",desc:"two-step word problems solved with an equation using a letter, and checking that the answer is reasonable",html:()=>`<p class="big" style="margin-top:0">The cider stand started the day with 150 cider donuts. It sold 62 donuts before lunch and 45 donuts after lunch.</p>`,qs:["Tess filled 7 baskets with 8 apples in each basket. She gave 15 of those apples to Mr. Park. How many apples does she have left? Write an equation with a letter for what you do not know.","Use rounding to show that your answer makes sense.","How many cider donuts are left at the stand? Write an equation with a letter for what you do not know. Then solve.","Use rounding to show that your donut answer makes sense. Round each number to the nearest ten."],key:["41 apples. 7 × 8 = 56, then 56 - 15 = 41. An equation such as (7 × 8) - 15 = a, or 56 - 15 = a, counts. Or: 7 × 8 = b and b - 15 = a written as two equations, as long as the letter stands for the unknown. Partial: 56 stops at the baskets and leaves the 15 out, so it is approaching. (3.OA.D.8)","About 60 take away about 15 is about 45, so 41 is close to what we expect. Any rounding that lands near 41 counts. Partial: an estimate with no comparison to the answer is approaching. (3.OA.D.8)","43 donuts. 62 + 45 = 107, then 150 - 107 = 43. An equation such as 150 - (62 + 45) = d counts. Or: 150 - 62 = 88 and 88 - 45 = d, taking the two sales off one at a time. The unknown has to be a letter, not a blank. Partial: 88 takes only the morning sales off and leaves the 45 out, so it is approaching, and so is the right answer with no letter for the unknown. (3.OA.D.8)","About 40. 62 rounds to 60 and 45 rounds to 50, so 150 - 110 is about 40, and 43 is close to that. Or: rounding to the nearest ten on each step, 150 - 60 is about 90 and 90 - 50 is about 40. Any rounding that lands near 43 counts. Partial: an estimate with no comparison to the answer is approaching. (3.OA.D.8, rounding to check)"]},{title:"Round It",std:["3.NBT.A.1"],n:3,dur:45,dir:"Answer out loud.",desc:"rounding whole numbers to the nearest ten and the nearest hundred",html:()=>`<p class="big" style="text-align:center">476 apples were picked on Saturday.</p>`,qs:["Round 476 to the nearest ten.","Round 476 to the nearest hundred.","The sign says about 350 visitors came, rounded to the nearest ten. Could the real number have been 347? Tell why."],key:["480. The ones digit is 6, so it goes up. Partial: 470 rounds down when the ones digit is 6 and does not count. (3.NBT.A.1)","500. The tens digit is 7, so it goes up. Partial: 400 rounds down when the tens digit is 7 and does not count. (3.NBT.A.1)","Yes. 347 is between 345 and 355, so it rounds to 350. Partial: saying yes with no range given is approaching. (3.NBT.A.1)"]}]},{id:16,title:"Share the Pie",short:"Fractions",parts:[{title:"Name the Fraction",std:["3.NF.A.1","3.NF.A.2"],n:3,dur:45,dir:"Look at the pie bar and the number line. Answer out loud.",desc:"naming a fraction of a whole and finding a fraction on a number line",fig:()=>`<div class="figure" style="flex-direction:column;align-items:center;gap:16px">${F.fracBar(6,5,{width:420})}${F.numberLine({min:0,max:1,step:1/6,labelEvery:1,marks:[4/6],width:560})}</div>`,qs:["The pie bar is cut into 6 equal pieces. 5 of them are shaded. What fraction is shaded?","What does the bottom number 6 tell you?","The number line runs from 0 to 1 and is cut into the same 6 equal parts. What fraction does the dot sit on?"],key:["5/6, five sixths. Partial: 5 given with no fraction form is approaching. (3.NF.A.1)","The whole was cut into 6 equal parts, so each part is one sixth. The top number tells how many of those parts we have. Partial: naming the 6 parts with nothing said about the top number is approaching. (3.NF.A.1)","4/6, four sixths. Counting 4 equal jumps of one sixth from 0 is the reasoning the standard asks for. Partial: 4/6 right with no count of jumps from 0 is approaching. (3.NF.A.2)"]},{title:"Same Size, Different Name",std:["3.NF.A.3"],n:3,dur:45,dir:"Look at the two bars. Answer out loud.",desc:"finding an equivalent fraction and comparing two fractions with the same numerator",fig:()=>`<div class="figure" style="flex-direction:column;align-items:center;gap:12px">${F.fracBar(2,1,{width:420})}${F.fracBar(4,2,{width:420})}</div>`,qs:["The two bars are the same size. The top one shows 1/2 and the bottom one shows 2/4. Are those two fractions equal? How do you know?","Name a fraction with 8 on the bottom that is equal to 1/2.","Which is bigger, 3/4 of one of these bars or 3/8 of one of these bars? Tell why."],key:["Yes, they are equal. The shaded part of each bar covers the same amount of the same size whole. Partial: saying yes with no reason from the bars is approaching. (3.NF.A.3)","4/8. Partial: 2/8 or 8/8 does not count. (3.NF.A.3)","3/4. Both have 3 pieces, but fourths are bigger pieces than eighths because the whole was cut into fewer parts. Partial: naming 3/4 with no reason is approaching. (3.NF.A.3)"]}]},{id:17,title:"Measure and Tile",short:"Measure",parts:[{title:"To the Nearest Quarter Inch",std:["3.MD.B.4"],n:4,dur:105,dir:"Look at the ruler and the line plot. Answer out loud. For the last one, get a ruler and measure.",mats:["a ruler"],desc:"measuring to the nearest quarter inch, generating measurements of real objects with a ruler, and reading a line plot of measurements",fig:()=>`<div class="figure" style="flex-direction:column;align-items:center;gap:14px">${F.ruler({length:4,unit:"in",item:2.75,itemLabel:"twig",parts:4})}${dotPlot({min:2,max:3,step:.25,counts:{2:1,2.25:3,2.5:4,2.75:2,3:2},labels:{2.25:"2 1/4",2.5:"2 1/2",2.75:"2 3/4"},title:"Twigs measured, in inches",alt:"A dot plot of twig lengths from 2 to 3 inches in quarter inch steps"})}</div>`,qs:["How long is the twig on the ruler?","On the line plot, how many twigs measured 2 and a half inches?","How many twigs were measured in all?","Now you are the measurer. Find three small things at your table. Something like a pencil. Or an eraser. Or a paper clip. Measure each one with your ruler. Say what each thing is. Say how long it is, to the nearest quarter inch."],key:["2 3/4 inches, two and three quarter inches. Partial: 3 inches rounds to a whole and is approaching. (3.MD.B.4)","4 twigs. Partial: counting the Xs above a different mark does not count. (3.MD.B.4)","12 twigs (1 + 3 + 4 + 2 + 2 = 12). Partial: four of the five stacks counted is approaching. (3.MD.B.4)","Three objects of the student's own choosing, each measured and named with a length. Watch the 0 end of the ruler line up with the end of the object, and listen for a length to the nearest quarter inch (a whole, 1/4, 1/2, or 3/4) with the unit inches said. Write the three objects and lengths on the record sheet, and have the student hold one object on the ruler up to the camera so you can check that reading yourself. Or: any three objects count, since these are the student's own data and there is no fixed answer. Partial: three lengths given but all rounded to whole inches, or the ruler started at the 1 instead of the 0, is approaching. (3.MD.B.4)","The measuring has to start at 0. Reading the quarter inch marks is the part to watch."]},{title:"Cover the Crate Lid",std:["3.MD.C.7","3.G.A.2"],n:3,dur:60,dir:"Look at the crate lid. Answer out loud.",desc:"finding the area of a rectangle by multiplying side lengths, and naming one of four equal parts as a unit fraction with its own area",fig:()=>`<div class="figure">${F.gridRect(4,6,0,{cell:44})}</div>`,qs:["The crate lid is covered with square tiles. How many rows are there. How many tiles in each row?","What is the area of the lid in square tiles? How did you get it?","Now picture the lid cut into 4 equal parts. What fraction of the lid is one part. How many square tiles is that?"],key:["4 rows with 6 tiles in each row. Partial: one of the two counts given is approaching. (3.MD.C.7)","24 square tiles. 4 × 6 = 24. Counting every tile gets the same number, so note whether the student multiplied. Partial: 24 with no square unit named is approaching. (3.MD.C.7)","One part is 1/4 of the lid, and it is 6 square tiles (24 ÷ 4 = 6). The four parts have to be equal in area. Partial: the fraction right with no number of tiles given is approaching. (3.G.A.2)"]}]},{id:18,title:"Scent and the Hive",short:"Senses",parts:[{title:"Sense, Brain, Act",std:["3-LS1-1"],n:3,dur:90,dir:"Answer out loud. For the last one, draw your model on your paper and hold it up.",desc:"using a model to show how an animal takes in information, processes it, and responds",html:()=>`<p class="big">A honeybee flies over the orchard rows. She has long antennae. They pick up scent out of the air. She passes two rows of bare branches. Then she turns sharply toward a row in bloom.</p>
     <div class="figure">${F.icon("bee",96)}${F.icon("nose",80)}${F.icon("purpleFlower",88)}</div>`,qs:["Which part of the bee took in the information about the blossom?","The bee turned toward one row and not the others. What had to happen inside her before she could turn?","Make a three-step model of this on paper, with arrows, and label each step."],key:["Her antennae, which pick up scent. Accept smelling with the antennae. (3-LS1-1)","The scent information went to her brain, and the brain worked out which way the strongest scent came from and decided to turn. (3-LS1-1)","Three parts in order with arrows: antennae or smells the blossom, then brain, then turns toward the row. The order is what is rated. A model with nothing in the middle is incomplete. (3-LS1-1)"]},{title:"A Hive Is a Group",std:["3-LS2-1"],n:3,dur:75,dir:"Look at the table. Answer out loud.",desc:"building an argument from data that forming a group helps animals survive",html:()=>`<p class="big">Some bees live alone and some live in a hive of thousands. A beekeeper measured both through a cold week.</p>
     <table class="bigTable"><tr><th>Bees</th><th>Warmest spot inside the nest</th><th>Food still stored after the cold week</th></tr>
     <tr><td>a bee living alone in a hollow stem</td><td>4 C</td><td>none</td></tr>
     <tr><td>a hive of several thousand bees</td><td>33 C</td><td>plenty</td></tr></table>`,qs:["Which nest stayed warmer through the cold week?","Make an argument that living in a hive helps a bee survive. Use a number from the table.","Thousands of bees in one hive also means more mouths to feed. Name one job the group can do that one bee alone cannot."],key:["the hive, 33 C against 4 C (3-LS2-1)","The claim yes, with the numbers attached: the hive held 33 C while the lone bee’s stem was 4 C, and the hive still had food left, so a bee in a hive is more likely to live through cold. A yes with no number is not yet an argument. (3-LS2-1)","Any real group job: many bees shiver together to keep the nest warm, guards block the entrance, scouts bring back news of flowers, bees store food for the whole hive, workers care for the young. (3-LS2-1)"]}]},{id:19,title:"Trees and Their Young",short:"Traits",parts:[{title:"Passed Down and Shaped",std:["3-LS3-1","3-LS3-2"],n:4,dur:120,dir:"Look at both tables. Answer out loud.",desc:"reading trait data for parents and offspring, naming the variation, and telling when the surroundings shaped a trait",html:()=>`<p class="big">Table 1: a red-fruited apple tree and four young trees grown from its seeds.</p>
     <table class="bigTable"><tr><th>Tree</th><th>Fruit color</th><th>Leaf length in cm</th></tr>
     <tr><td>parent tree</td><td>red</td><td>9</td></tr>
     <tr><td>young tree A</td><td>red</td><td>7</td></tr><tr><td>young tree B</td><td>red</td><td>10</td></tr>
     <tr><td>young tree C</td><td>red</td><td>8</td></tr><tr><td>young tree D</td><td>red</td><td>11</td></tr></table>
     <p class="big">Table 2: two cuttings taken off the same parent tree and planted the same spring.</p>
     <table class="bigTable"><tr><th>Cutting</th><th>Where it was planted</th><th>Apples picked this fall</th></tr>
     <tr><td>cutting 1</td><td>deep soil at the bottom of the row</td><td>46</td></tr>
     <tr><td>cutting 2</td><td>thin rocky soil at the end of the row</td><td>9</td></tr></table>`,qs:["Every young tree has red fruit, the same as the parent. Where did that trait come from?","The leaf lengths are all different. What is that difference called. Does it mean one of the young trees came from a different parent?","In Table 2 both cuttings came off the same tree. What made one pick 46 apples and the other 9?","A tree gives a number of apples. Is that decided only by the tree it came from? Explain."],key:["It was inherited from the parent tree. A trait the parent has and every offspring has is passed down. (3-LS3-1)","Variation. They are all still its offspring: inherited traits vary from one offspring to the next, so a group of similar organisms is not identical. (3-LS3-1)","The soil each one was planted in. Same parent, different surroundings, different crop. (3-LS3-2)","No. The environment shaped it too. Listen for the idea that a trait can be influenced by where a living thing grows, not by inheritance alone. (3-LS3-2)"]}]},{id:20,title:"Stone and Survival",short:"Fossils",parts:[{title:"Clues in the Quarry",std:["3-LS4-1"],n:3,dur:90,dir:"Look at the table of rock layers. Answer out loud.",desc:"reading fossil data to say which organisms lived in a place and what the place was like",html:()=>`<p class="big">Behind the orchard is an old stone quarry. A class wrote down the fossils in each layer. The top layer is the youngest.</p>
     <table class="bigTable"><tr><th>Layer</th><th>Fossils found</th></tr>
     <tr><td>top</td><td>pine cones, a beetle</td></tr>
     <tr><td>middle</td><td>broad leaf prints, a dragonfly wing</td></tr>
     <tr><td>bottom</td><td>clam shells, a snail, fish scales</td></tr></table>
     <div class="figure">${F.icon("shell",80)}${F.icon("leaf",80)}${F.icon("pine",80)}</div>`,qs:["Name two organisms that once lived where this quarry is now.","Was the bottom layer once underwater or once dry ground? Use the fossils as your evidence.","The middle layer has broad leaves and a dragonfly but no clams. What does that tell you had changed by then?"],key:["Any two the table names: a pine, a beetle, a broad-leaved plant, a dragonfly, a clam, a snail, a fish. (3-LS4-1)","Underwater. Clams, snails and fish live in water, and naming them is the evidence. An answer with no fossil named is not yet using the data. (3-LS4-1)","The water was gone and the place had become land, probably damp land near water, since dragonflies live near water but clams need to be in it. (3-LS4-1)"]},{title:"A Useful Difference",std:["3-LS4-2"],n:3,dur:90,dir:"Look at the table. Answer out loud.",desc:"explaining how a variation among individuals of one species gives an advantage",html:()=>`<p class="big">Ground beetles live under the orchard grass, and birds hunt them. A class measured legs and timed how fast each beetle crossed a path.</p>
     <table class="bigTable"><tr><th>Beetles</th><th>Back leg length</th><th>Time to cross the path</th><th>Caught by birds in a week</th></tr>
     <tr><td>short back legs</td><td>4 mm</td><td>9 seconds</td><td>14</td></tr>
     <tr><td>long back legs</td><td>7 mm</td><td>4 seconds</td><td>3</td></tr></table>`,qs:["Which beetles crossed the open path faster?","Explain why long back legs are an advantage for a beetle in this orchard. Use the table.","Long-legged beetles also left more young behind. How can a trait that helps a beetle escape end up giving it more young?"],key:["the long-legged beetles, 4 seconds against 9 (3-LS4-2)","Long legs cross the open ground faster, so fewer are caught, 3 against 14. A beetle that is not caught survives in a place where birds hunt. The explanation has to lean on the data. (3-LS4-2)","A beetle that survives longer has more chances to find a mate and lay eggs. Accept any version that links surviving to finding mates or reproducing. (3-LS4-2)"]}]},{id:21,title:"A Cold Wet Autumn",short:"Habitat",parts:[{title:"Who Survives, and What Would Help",std:["3-LS4-3","3-LS4-4"],n:4,dur:120,dir:"Read the table. Answer out loud.",desc:"arguing from data who can survive in a changed habitat, then judging the merit of a solution",html:()=>`<p class="big">One autumn stayed cold and rainy for eight weeks. The orchard keeper wrote down what she found in the rows.</p>
     <table class="bigTable"><tr><th>Living thing</th><th>What happened that autumn</th></tr>
     <tr><td>moss on the north wall</td><td>spread across twice as much wall as usual</td></tr>
     <tr><td>honeybees</td><td>far fewer flying, and little food stored</td></tr>
     <tr><td>monarch butterflies</td><td>none seen in the orchard at all</td></tr></table>`,qs:["Which living thing survived well in that cold wet autumn? Give the evidence.","Which one was gone from the orchard altogether. Which one only did worse?","The keeper wants to move the hives into a dry shed for the next cold autumn. Would that help the bees? Name one drawback.","A second plan is to plant a row of late-blooming flowers along the fence. Which plan has more merit, and why?"],key:["The moss. It spread over twice its usual patch, so the cold and the wet suited it. (3-LS4-3)","The monarch butterflies could not survive there at all, none were seen. The honeybees survived less well, fewer flying and little food stored. (3-LS4-3)","Yes, a dry shed keeps the hive out of the rain and holds its warmth. Then any real drawback: bees shut in cannot gather food, the shed has to be opened and closed by someone, the hive may get too warm, it does nothing for the monarchs. A claim with no drawback is half of this standard. (3-LS4-4)","Either plan can earn credit. What is rated is the reasoning: the shed protects only the hives that are moved, while late flowers add food for bees and butterflies both, though flowers do nothing about the rain. (3-LS4-4)"]}]},{id:22,title:"Weather and Climate",short:"Weather",parts:[{title:"A Season of Weather",std:["3-ESS2-1"],n:3,dur:90,dir:"Look at the table. Answer out loud. For the last one, draw your graph on your paper and hold it up.",desc:"reading and making a graphical display of typical weather for one season",html:()=>`<p class="big">The keeper records the highest temperature on the first day of every week of picking season.</p>
     <table class="bigTable"><tr><th>Week</th><th>Highest temperature</th></tr>
     <tr><td>1</td><td>24 C</td></tr><tr><td>2</td><td>22 C</td></tr>
     <tr><td>3</td><td>18 C</td></tr><tr><td>4</td><td>16 C</td></tr><tr><td>5</td><td>15 C</td></tr></table>
     <div class="figure">${F.icon("thermometer",88)}${F.icon("apple",88)}</div>`,qs:["What is happening to the temperature across picking season?","A sixth week of picking season is coming. What temperature would you expect, and why?","Draw a bar graph of the five weeks. Label both sides."],key:["It is falling week by week, from 24 C down to 15 C. (3-ESS2-1)","Somewhere near 14 C or 15 C, because the table drops a degree or two each week. Any answer in that range with the trend named as the reason. (3-ESS2-1)","Five bars in week order with heights that match 24, 22, 18, 16 and 15, a label on the week side and a label on the temperature side. A graph with no labels is incomplete. (3-ESS2-1)"]},{title:"Two Parts of the World",std:["3-ESS2-2"],n:3,dur:75,dir:"Look at the table. Answer out loud.",desc:"combining information to describe the climates of two different regions of the world",html:()=>`<p class="big">Apples grow well in some regions of the world and badly in others.</p>
     <table class="bigTable"><tr><th>Region</th><th>Summer</th><th>Winter</th><th>Rain in a year</th></tr>
     <tr><td>a river valley where apples grow</td><td>warm and dry</td><td>cold, some frost</td><td>75 cm</td></tr>
     <tr><td>a desert region</td><td>very hot</td><td>mild, no frost</td><td>9 cm</td></tr></table>
     <div class="figure">${F.icon("apple",80)}${F.icon("cactus",80)}</div>`,qs:["Which region gets far less rain in a year?","Which region has frost in winter. What in the table tells you?","Give one reason why two regions of the world end up with different climates."],key:["the desert region, 9 cm against 75 cm (3-ESS2-2)","the river valley, because the table says its winter is cold with some frost (3-ESS2-2)","Any sound reason: how near a region is to the middle of the globe, how high it sits above sea level, how near it is to an ocean, whether mountains block the rain. One solid reason is enough here. (3-ESS2-2)"]},{title:"Ready for the Hail",std:["3-ESS3-1"],n:3,dur:90,dir:"Answer out loud.",desc:"making a claim about the merit of a design that reduces the impact of a weather hazard",html:()=>`<p class="big">A hailstorm can bruise a whole row of apples. It takes ten minutes. The keeper stretches a net on poles above each row. It is high enough for a picker to walk under.</p>
     <div class="figure">${F.icon("cloud",88)}${F.icon("tree",88)}</div>`,qs:["Which weather hazard is the net meant to reduce?","Make a claim. Does the net have merit? Give your reason.","Name one thing the net does not protect the orchard from."],key:["hail, which bruises the fruit (3-ESS3-1)","Yes, with a reason attached: the hail strikes the net instead of the fruit, so the apples are not bruised. A yes with no reason is not yet a claim. (3-ESS3-1)","Any real limit: frost, wind, heavy rain, a dry year, insects, the poles blowing over, the net shading the fruit. (3-ESS3-1)"]}]},{id:23,title:"Carts and Belts",short:"Forces",parts:[{title:"Balanced or Not",std:["3-PS2-1"],n:4,dur:105,dir:"Answer out loud.",desc:"planning an investigation of balanced and unbalanced forces acting on an object",html:()=>`<p class="big">A cart loaded with apple crates stands on the sloped lane. The brake block is wedged under one wheel. The cart does not move.</p>
     <div class="figure">${F.icon("tractor",96)}${F.icon("box",80)}</div>`,qs:["The slope is pulling the cart downhill. The cart stays still. Are the forces on it balanced or unbalanced? How do you know?","Someone pulls the brake block out. What happens, and what changed about the forces?","Plan an investigation to find out. A brake block holds the cart. How many crates can it hold? Find the point where the block stops holding. What will you change? What will you measure?","Which things have to stay the same from one test to the next?"],key:["Balanced. The block pushes back exactly as hard as the slope pulls, and the cart staying still is the evidence. (3-PS2-1)","The cart rolls downhill. Now nothing balances the pull of the slope, so the forces are unbalanced. (3-PS2-1)","A plan with one thing changed and one thing measured: load one more crate at a time (the change) and watch for the load at which the cart first creeps or rolls (the measure). (3-PS2-1)","Any controlled variable that fits the plan: the same cart, the same lane and slope, the same block in the same spot, the same dry weather, crates of the same weight. (3-PS2-1)"]},{title:"Predict the Next Apple",std:["3-PS2-2"],n:3,dur:90,dir:"Look at the table. Answer out loud.",desc:"using a pattern in motion data to predict where an object will be later",html:()=>`<p class="big">Apples ride a sorting belt past a counting window. A class timed one apple as it passed the marks painted on the belt rail.</p>
     <table class="bigTable"><tr><th>Seconds</th><th>Marks passed</th></tr>
     <tr><td>4</td><td>1</td></tr><tr><td>8</td><td>2</td></tr><tr><td>12</td><td>3</td></tr></table>`,qs:["What is the pattern in the table?","Which mark will the apple be at after 20 seconds? How do you know?","What could change on the belt that would spoil your prediction?"],key:["One mark every 4 seconds, the same time for each one. (3-PS2-2)","mark 5, because 20 seconds divided into 4-second steps is five marks. The reason has to be the pattern, not a guess. (3-PS2-2)","A new force acting on the belt or the apple: the belt is sped up or slowed down, it stops, the apple is lifted off or jams. A pattern only predicts while nothing changes. (3-PS2-2)"]}]},{id:24,title:"Pulling Without Touching",short:"Magnets",parts:[{title:"Ask About the Pull",std:["3-PS2-3"],n:3,dur:90,dir:"Answer out loud. Your two questions have to be questions, not statements.",desc:"asking questions about cause and effect in electric or magnetic interactions between objects not touching",html:()=>`<p class="big">A balloon is rubbed on a wool sleeve and held just above a dry apple leaf on the table. The leaf lifts off the table toward the balloon. The balloon never touches it.</p>
     <div class="figure">${F.icon("balloons",88)}${F.icon("leaf",80)}</div>`,qs:["The balloon never touches the leaf, yet the leaf lifts. What does that tell you about this force?","Think of two questions about this that you could find out by testing.","The balloon only does this after it has been rubbed on wool. What does the rubbing have to do with it?"],key:["The force acts across a distance, with no contact between the objects. (3-PS2-3)","Any two real investigable questions: how close does the balloon have to be, does rubbing it longer lift the leaf higher, does a wet leaf lift, does a plastic ruler work instead, does it still work on a damp day. A statement is not a question, so ask once more. (3-PS2-3)","Rubbing gives the balloon an electric charge, and the charge is the cause of the pull. Accept static electricity named in the student’s own words. (3-PS2-3)"]},{title:"A Problem for a Magnet",std:["3-PS2-4","3-5-ETS1-1"],n:4,dur:105,dir:"Answer out loud. For the third one you may write your two sentences on your paper.",desc:"defining a design problem that magnets can solve, with criteria for success and constraints",html:()=>`<p class="big">The steel pins that hold the picking ladders together keep working loose and dropping into the deep grass. They are hard to see. A pin left in the grass can go through a tire.</p>
     <div class="figure">${F.icon("ruler",80)}${F.icon("key",80)}${F.icon("herb",80)}</div>`,qs:["State the problem in one sentence. Start with the words: The problem is.","Why is a magnet a sensible idea here? Would the same tool find a dropped plastic cap in the same grass?","Write two things the tool has to do before you would call it a success.","You may use three things only. A broom handle, one magnet, and a strip of tape. You have fifteen minutes. What limits does that put on your design?"],key:["A problem statement about finding and picking up steel ladder pins out of deep grass. The problem has to be about the lost pins, not about the ladders being loose. (3-PS2-4)","The pins are steel, and a magnet pulls steel without touching it, so it can lift pins the eye cannot see down in the grass. A plastic cap is not pulled by a magnet, so no. (3-PS2-4)","Two criteria, written as what the tool must do: find every pin, reach the soil under the grass, work without bending down, hold the pins while you walk, be quick enough to use on a whole row. (3-5-ETS1-1)","Names the limits as limits: only three materials, only one magnet, only fifteen minutes. Materials, time and cost are the constraints to listen for. (3-5-ETS1-1)"]}]},{id:25,title:"Compare and Test",short:"Design",parts:[{title:"Three Ways to Do It",std:["3-5-ETS1-2"],n:3,dur:90,dir:"Look at the table and the three rules. Answer out loud.",desc:"comparing several possible solutions against stated criteria and constraints",html:()=>`<p class="big">Pickers need something to carry apples in while both hands are up in the tree. Three designs are tried.</p>
     <table class="bigTable"><tr><th>Design</th><th>Holds</th><th>Hands free?</th><th>Bruised apples out of 50</th></tr>
     <tr><td>wire basket on the arm</td><td>20 apples</td><td>no</td><td>2</td></tr>
     <tr><td>canvas bag on a shoulder strap</td><td>35 apples</td><td>yes</td><td>3</td></tr>
     <tr><td>bucket hooked to the belt</td><td>15 apples</td><td>yes</td><td>11</td></tr></table>
     <p class="big">The rules for success: hold at least 20 apples, leave both hands free, bruise no more than 5 apples out of 50.</p>`,qs:["Which design holds the most apples?","Which one meets all three rules? Use the table to explain.","Choose a design you would reject. Then say which rule it breaks."],key:["the canvas bag, 35 apples (3-5-ETS1-2)","The canvas bag. It holds 35, leaves both hands free, and bruises only 3 out of 50. Another choice counts only if the student argues it against all three rules using the table. (3-5-ETS1-2)","Any reasoned rejection with the rule named: the wire basket fails the hands-free rule, the belt bucket fails the amount rule at 15 and the bruising rule at 11. Naming the rule is the part being rated. (3-5-ETS1-2)"]},{title:"Make the Test Fair",std:["3-5-ETS1-3"],n:3,dur:90,dir:"Answer out loud.",desc:"judging whether a test is fair, naming controlled variables, and identifying a failure point",html:()=>`<p class="big">Two ladder feet were tested to see which one slips less on wet grass.</p>
     <table class="bigTable"><tr><th>Foot</th><th>Ground</th><th>Weight on the ladder</th></tr>
     <tr><td>wide rubber pad</td><td>wet grass</td><td>one picker</td></tr>
     <tr><td>narrow steel spike</td><td>dry packed dirt</td><td>two pickers</td></tr></table>`,qs:["Was that a fair test? Explain.","Which two things would you hold the same to make it fair?","The wide rubber pad slid every time the ladder was leaned past halfway over. Name that weak spot. Then say what you would change about the design."],key:["No. Two things were different at once, the ground and the weight, so a slip cannot be pinned on the foot. (3-5-ETS1-3)","Any two controlled variables: the same ground, the same weight on the ladder, the same lean, the same ladder, the same weather. (3-5-ETS1-3)","The failure point is the pad slipping when the ladder is leaned far over. Any improvement aimed at that: add a spike through the pad, widen the base, add a strap to the trunk, mark a safe lean limit. An improvement somewhere else does not count. (3-5-ETS1-3)"]}]},{id:26,title:"Maps and Places",short:"Maps",parts:[{std:["HSS-3.1"],n:4,dur:90,dir:"Use the map grid and the table. Answer out loud.",desc:"using a map grid and a table to describe physical and human features and where they sit",html:()=>`<p class="big">A map grid of the orchard and the land around it. North is the top row.</p>
     <table class="bigTable"><tr><th></th><th>west</th><th>middle</th><th>east</th></tr>
     <tr><th>north</th><td>${F.icon("mountain",54)}<br>hills</td><td>${F.icon("tree",54)}<br>old oak wood</td><td>${F.icon("wateringCan",54)}<br>well</td></tr>
     <tr><th>middle</th><td>${F.icon("drop",54)}<br>creek</td><td>${F.icon("apple",54)}<br>apple rows</td><td>${F.icon("cabin",54)}<br>farm stand</td></tr>
     <tr><th>south</th><td>${F.icon("corn",54)}<br>corn field</td><td>${F.icon("bridge",54)}<br>creek bridge</td><td>${F.icon("bus",54)}<br>main road</td></tr></table>
     <table class="bigTable"><tr><th>Place</th><th>Distance from the apple rows</th></tr>
     <tr><td>farm stand</td><td>200 m</td></tr><tr><td>well</td><td>350 m</td></tr>
     <tr><td>creek bridge</td><td>500 m</td></tr><tr><td>hills</td><td>900 m</td></tr></table>`,qs:["What lies directly west of the apple rows?","Which two directions do you walk to get from the apple rows to the corn field?","Point out one natural feature on this map. Point out one thing people made. Then name one thing that shows people changing the land. They changed it in order to use a resource.","Which place in the table is nearest the apple rows? If you drew a bar graph of the table, which bar would be shortest?"],key:["the creek (HSS-3.1)","south and west, in either order. The corn field sits in the south row and the west column. Partial: one of the two directions is approaching. (HSS-3.1)","Physical: the hills, the creek, the old oak wood. Human-made: the apple rows, the well, the farm stand, the bridge, the main road. For the last part, any of: the well dug down to reach the water, the apple rows planted where the wood used to stand, the bridge put across the creek, the road cut through. One of each of the three is what is being checked. Partial: two of the three parts given is approaching. (HSS-3.1)","the farm stand, 200 m, and its bar would be the shortest. Partial: the nearest place named with no answer about the bar is approaching. (HSS-3.1)"]}]},{id:27,title:"Long Ago in This Place",short:"Long Ago",parts:[{title:"The First Nations Here",std:["HSS-3.2"],n:3,dur:90,dir:"Answer out loud. Use what is on the screen and what you have learned.",desc:"describing how the American Indian nations of California used the plants around them long ago and how a nation is part of the state today",html:()=>`<p class="big">Many California nations are known for basket making. Weavers cut willow and other plants. They cut when the stems were right. That was one time of year. They split them by hand. They wove baskets so tight that some of them held water.</p>
     <div class="figure">${F.icon("herb",88)}${F.icon("box",80)}</div>`,qs:["The screen gives three steps the weavers took to make a basket. Name all three, in order, and say what the tightest baskets could do.","What does basket making tell you about what people here knew about the plants around them?","Are these nations only history? Name one way a nation is part of California now."],key:["Cut the willow or other plants at the time of year when the stems were right, split them by hand, then wove them. The tightest baskets held water. Partial: the three steps right with nothing said about holding water, or holding water right with only two of the steps, is approaching. (HSS-3.2)","They knew their local plants closely: which ones to use, when in the year to cut them, and how to prepare them. Listen for knowledge of the local land rather than a memorized list. Partial: listing plants with nothing said about what the people knew is approaching. (HSS-3.2)","No. Any true present-day answer: nations have their own tribal governments, basket weavers still teach the work, there are language classes and cultural centers, nations care for land and water, members live and work across the state. Partial: saying no with no present-day example is approaching. (HSS-3.2)","Not scored, ask it anyway: which American Indian nation or nations have their homeland where this student lives? The answer is different for every family, so there is no key for it and it stays out of the rating. Tell the student the name if they do not know it, write it on the record sheet, and make it something to teach before the next check."]},{title:"A Town Over Time",std:["HSS-3.3"],n:3,dur:90,dir:"Look at the timeline. Answer out loud.",desc:"sequencing local historical events and describing the mark each period left on the land",html:()=>`<p class="big">A timeline for the town of Mill Hollow.</p>
     <table class="bigTable"><tr><th>Year</th><th>What happened</th></tr>
     <tr><td>1844</td><td>a flour mill is built on the creek, and a pond is dug behind a dam</td></tr>
     <tr><td>1869</td><td>farmers clear the oak flats and plant the first apple rows</td></tr>
     <tr><td>1901</td><td>a packing shed and a rail siding are built at the edge of town</td></tr>
     <tr><td>1954</td><td>the mill closes and the dam is taken out</td></tr>
     <tr><td>1998</td><td>the packing shed becomes a farm stand and a museum</td></tr></table>
      <p class="big">People came to Mill Hollow from many places. Irish and German families worked the flour mill. Chinese workers built the rail siding, and later ran the town’s first laundry and its first grocery. Portuguese and Italian families planted most of the apple rows. Mexican American families have grown and packed the fruit here for a hundred years. Each group brought its own language, its own food and its own faith, and the town has a Catholic church from 1871, a Protestant meeting house from 1884, and a Chinese temple that stood beside the siding until 1930.</p>`,qs:["Put these three in order, earliest first. The packing shed. The flour mill. The first apple rows.","Which event changed the oak flats. What did it do to them?","People came to this town from many different places. Name one group who came. Name one thing they built or did for the town. Name one tradition or faith they brought."],key:["flour mill, first apple rows, packing shed. Partial: two of the three in the right order is approaching. (HSS-3.3)","the clearing in 1869, which took out the oaks and put apple rows in their place. Partial: naming the clearing with no account of what it did to the flats is approaching. (HSS-3.3)","Any group on the page with a true pairing. Irish and German families worked the mill. Chinese workers built the rail siding and opened the first laundry and grocery. Portuguese and Italian families planted the apple rows. Mexican American families have grown and packed the fruit for a hundred years. Traditions and faiths on the page: their own language, their own food, the Catholic church, the Protestant meeting house, the Chinese temple. All three parts are needed for a full answer. Partial: two of the three parts given is approaching. (HSS-3.3)"]}]},{id:28,title:"Rules and Work",short:"Rules",parts:[{title:"Rules, Laws and Government",std:["HSS-3.4"],n:4,dur:105,dir:"Answer out loud.",desc:"telling rules from laws and naming the basic parts and levels of United States government",html:()=>`<p class="big">The farm stand has a rule posted by the door. No fruit tasting until it is weighed. There is also a county law. It says every price has to be posted. A buyer must be able to read it.</p>
      <p class="big">A country has symbols too. The United States flag carries thirteen stripes. Those are for the first thirteen states. It carries fifty stars for the states today. The bald eagle has stood for the country since 1782. The Statue of Liberty was a gift from France in 1886. It stands in New York harbor. The Capitol in Washington is the building where Congress meets.</p>
     <div class="figure">${F.icon("books",88)}${F.icon("flag",88)}</div>`,qs:["What is the difference between the stand’s own rule and the county law?","The United States government has three parts. Which part makes the laws, and what is it called?","Which part decides what a law means when people disagree about it?","Name two symbols or landmarks of the United States from what you read. Then say for each one what it stands for or what it is used for."],key:["The stand’s rule is set by the owner and applies at the stand. The county law is made by a government, applies to every seller in the county, and the government decides what happens when it is broken. Partial: describing the stand's rule with nothing said about who makes the county law is approaching. (HSS-3.4)","Congress, the lawmaking part, also called the legislative branch. Accept the state legislature named for a state law. (HSS-3.4)","the courts, the judicial branch (HSS-3.4)","Any two from the page, with the name and the meaning both given: the flag, thirteen stripes for the first states and fifty stars for the states today; the bald eagle, a symbol of the country since 1782; the Statue of Liberty, a gift from France in 1886 standing in New York harbor; the Capitol, the building where Congress meets. Partial: two symbols named with one meaning missing is approaching. (HSS-3.4)"]},{title:"Choices and the Local Economy",std:["HSS-3.5"],n:4,dur:105,dir:"Look at the table. Answer out loud.",desc:"basic economic reasoning about producers and consumers, scarcity, and goods and services",html:()=>`<p class="big">The farm stand sells apples and cider, and for a fee it will press a customer’s own fruit into juice.</p>
     <table class="bigTable"><tr><th>Year</th><th>Apples picked</th><th>Price for a bag</th></tr>
     <tr><td>a good year</td><td>9,000</td><td>4 dollars</td></tr>
     <tr><td>a hail year</td><td>2,000</td><td>7 dollars</td></tr></table>`,qs:["In which year was the price higher. What happened to the number of apples that year?","Why would fewer apples push the price up? Use the idea that there is not enough to go around.","The stand sells apples and it also presses fruit for a fee. Which of those is a good and which is a service?","Think of a job in your own town. Does that worker make a good or provide a service?"],key:["the hail year, 7 dollars a bag, and there were far fewer apples, 2,000 against 9,000. Partial: the year named with no account of the number of apples is approaching. (HSS-3.5)","When there are fewer apples than people want, apples are scarce, and buyers will pay more for the few that there are. Accept scarcity explained in the student’s own words. Partial: saying the price goes up with no account of there not being enough to go around is approaching. (HSS-3.5)","An apple is a good, something you can hold. Pressing fruit for a fee is a service, work someone does for you. Partial: one of the two sorted right is approaching. (HSS-3.5)","Any real local job sorted correctly: a baker makes a good, a dentist provides a service, a farmer produces a good, a mail carrier provides a service. Partial: a real job named with the good or service label wrong is approaching. (HSS-3.5)"]}]}];const WC=STORY.split(/\s+/).filter(Boolean).length;STOPS[2].parts[0].n=WC;STOPS[2].parts[0].key[0]=STOPS[2].parts[0].key[0].replace("__WC__",WC);STOPS[2].parts[0].desc=`a ${WC}-word grade-level story read aloud`;const LEVELUPS={4:{id:"L4",title:"Level Up: Read Between the Lines",std:["RL.4.1"],needs:["RL.3.1"],n:1,dir:"Answer out loud. Use details from the story.",html:()=>`<p class="big">Mr. Park said, “You can come down if you want.” Why do you think he said that? Give two details from the story that help you know.</p>${F.passage(STORY,STORY_TITLE,true)}`,key:["He could tell that Tess was scared, and he wanted her to know she did not have to keep going. Two details, such as: she climbed one step and stopped, her hands felt cold, the ground looked far away. The story never says she was scared, so this is an inference. (RL.4.1, inference with details)"]},7:{id:"L7",title:"Level Up: Grammar Grower",std:["L.4.1"],needs:["L.3.1"],n:3,dir:"Answer out loud.",html:()=>`<ol class="qlist"><li>Which one sounds right? A: a red small apple. B: a small red apple.</li><li>This sentence runs on without a stop. Say it the right way: We picked apples we made cider.</li><li>Pick the right word: (There, Their, They’re) baskets are full.</li></ol>`,key:["B, a small red apple. Size comes before color. (L.4.1, order of adjectives)","We picked apples, and we made cider. Two sentences, or another joining word such as then or so, are also correct. (L.4.1, fixing a run-on)","Their baskets are full. (L.4.1, words that are often mixed up)"]},8:{id:"L8",title:"Level Up: Times as Many",std:["4.OA.A.1"],needs:["3.OA.A.1"],n:2,dir:"Write the equation on your paper and hold it up. Then answer out loud.",html:()=>`<div class="figure" style="gap:40px">${group(looseApples(6,3),"Little tree: 6 apples")}${group(`<p class="huge" style="margin:0;font-size:4rem">?</p>`,"Big tree: 4 times as many")}</div><ol class="qlist"><li>The big tree has 4 times as many apples as the little tree. Write a multiplication equation. How many apples are on the big tree?</li><li>35 = 5 × 7. Finish the sentence: 35 is ____ times as many as ____.</li></ol>`,key:["4 × 6 = 24. The big tree has 24 apples. (4.OA.A.1)","35 is 5 times as many as 7, or 35 is 7 times as many as 5. (4.OA.A.1)"]},9:{id:"L9",title:"Level Up: Bee Detective",std:["RI.4.1"],needs:["RI.3.1"],n:1,dir:"Answer out loud. Use details from the text.",html:()=>`<p class="big">Farmers bring the beehives in spring, not in fall. Why do you think that is? Give two details from the text that help you know.</p>${F.passage(BEES,BEES_TITLE,true)}`,key:["Bees can only help when the trees have blossoms, and the blossoms are on the trees in spring. Details, such as: in spring the trees are covered with blossoms, bees carry pollen from blossom to blossom, the hives stay until the blossoms are gone. The text does not say this in one sentence, so the student has to put details together. (RI.4.1, inference with details)"]}};const PASSAGE_STD=["RL.3.1","RL.3.4","RI.3.1","RI.3.9","W.3.8","RL.4.1","RI.4.1"];const MULT_N=10;let multSel=[0,0],matN=3,matV=[0,0,0,0,0,0,0,0];function multHtml(){let h=`<div class="tool-scroll"><table class="mult"><tr><th>×</th>`;for(let c=1;c<=MULT_N;c++)h+=`<th data-r="0" data-c="${c}" class="${multSel[1]===c?"hl":""}">${c}</th>`;h+="</tr>";for(let r=1;r<=MULT_N;r++){h+=`<tr><th data-r="${r}" data-c="0" class="${multSel[0]===r?"hl":""}">${r}</th>`;for(let c=1;c<=MULT_N;c++){const hr=multSel[0]===r,hc=multSel[1]===c;h+=`<td data-r="${r}" data-c="${c}" class="${hr&&hc?"pick":hr||hc?"hl":""}">${r*c}</td>`}h+="</tr>"}return h+`</table></div><p class="small">Click a number to light up its row and column. Click it again to clear.</p>`}function matHtml(){let h=`<div style="display:flex;gap:8px;flex-wrap:wrap;justify-content:center">`;for(let i=0;i<matN;i++)h+=`<button class="btn ghost" data-mat="g${i}" style="padding:4px" aria-label="Crate ${i+1}">${box(matV[i],4,3,26)}</button>`;h+=`</div><div style="display:flex;gap:8px;flex-wrap:wrap;justify-content:center;margin-top:10px"><button class="btn ghost" data-mat="less">Fewer crates</button><button class="btn ghost" data-mat="more">More crates</button><button class="btn ghost" data-mat="all">Add 1 to every crate</button><button class="btn ghost" data-mat="clear">Empty the crates</button></div><p class="small">Click a crate to drop one apple in it. Each crate holds up to 12.</p>`;return h}function starters(st){if(st.std.includes("W.3.3"))return["One morning, ____.","First, ____.","Next, ____.","Then, ____.","In the end, ____."];if(st.std.includes("W.3.2"))return["Here is how apples become cider.","First, ____.","Next, ____.","Also, ____.","Now you know ____."];return["I think ____ is the better apple treat.","One reason is ____.","Also, ____.","For example, ____.","That is why ____."]}function sentHtml(st){return`<ul class="starters">${starters(st).map(x=>`<li>${x}</li>`).join("")}</ul>`}const TOOLS={mult:{name:"Multiplication chart",std:["3.OA.A.1","3.OA.A.2","3.OA.D.8","3.MD.C.7","4.OA.A.1"],html:multHtml,bind:(b,r)=>b.querySelectorAll("[data-r]").forEach(c=>c.onclick=()=>{const row=+c.dataset.r,k=+c.dataset.c;multSel=multSel[0]===row&&multSel[1]===k?[0,0]:[row,k];r()})},mat:{name:"Equal groups mat",std:["3.OA.A.1","3.OA.A.2","3.OA.D.8"],html:matHtml,bind:(b,r)=>b.querySelectorAll("[data-mat]").forEach(x=>x.onclick=()=>{const k=x.dataset.mat;if(k==="less")matN=Math.max(1,matN-1);else if(k==="more")matN=Math.min(8,matN+1);else if(k==="all"){for(let i=0;i<matN;i++)matV[i]=Math.min(12,matV[i]+1)}else if(k==="clear")matV=matV.map(()=>0);else{const i=+k.slice(1);matV[i]=Math.min(12,matV[i]+1)}r()})},sent:{name:"Sentence starters",std:["W.3.1","W.3.2","W.3.3"],html:sentHtml}};const SUP_CAVEATS=[{t:"mult",std:["3.OA.A.1","3.OA.A.2","4.OA.A.1"],msg:"The multiplication chart gives the totals. These stops are about what the numbers mean, so rate on the student’s explanation, story, or drawing."},{t:"mat",std:["3.OA.A.1","3.OA.A.2"],msg:"With the equal groups mat the student can count out the answer. Rate on whether the student can say what each number in the equation means."},{t:"sent",msg:"Sentence starters supply the linking or time words and the closing, so count those checks as supported, not independent."},{t:"passage",std:["RL.3.1","RL.3.4","RI.3.1","RI.3.9","RL.4.1","RI.4.1"],msg:"If the passage was read to the student, this stop shows listening comprehension, not reading."},{t:"mult",std:["3.OA.D.8","3.MD.C.7"],msg:"The multiplication chart supplies the product. Rate the two step problem on the steps and the equation, and the area item on whether the student multiplied the side lengths rather than counting tiles."}];return{stops:STOPS,levelups:LEVELUPS,tools:TOOLS,supCaveats:SUP_CAVEATS,passageStd:PASSAGE_STD}}});
